INSERT INTO CLAIM_NOTES (CLAIM_ID, NOTE_ID, NOTE_DATE, AUTHOR_ID, AUTHOR_ROLE, NOTE_TYPE, CONTENT, SUMMARY, ACTION_REQUIRED, ACTION_DUE_DATE, EXTRACTED_ENTITIES, KEY_FINDINGS) VALUES
  ('CLM00000000', 'CN00000000', '2026-02-17T14:29:13.959000', 'ADJ0000', 'CLAIMS_ADJUSTER', 'INITIAL_ASSESSMENT', 'Initial claim assessment completed. Policyholder reported collision at Main St and Oak Ave intersection. Police report obtained confirms other party at fault. Vehicle damage appears consistent with reported incident. Recommend proceeding with standard processing. Estimated repair cost: $2000. Coverage verified - comprehensive and collision in force.', 'Initial assessment complete; recommend standard processing', TRUE, '2026-02-20', 'Location: Main St/Oak Ave; Vehicle: 2022 Toyota Camry; Amount: $2000', 'Damage consistent with reported incident; coverage verified'),
  ('CLM00000000', 'CN00003000', '2025-07-24T07:29:13.959000', 'ADJ0000', 'CLAIMS_ADJUSTER', 'INITIAL_ASSESSMENT', 'Initial claim assessment completed. Policyholder reported collision at Main St and Oak Ave intersection. Police report obtained confirms other party at fault. Vehicle damage appears consistent with reported incident. Recommend proceeding with standard processing. Estimated repair cost: $5000. Coverage verified - comprehensive and collision in force.', 'Initial assessment complete; recommend standard processing', TRUE, '2026-02-24', 'Location: Main St/Oak Ave; Vehicle: 2022 Toyota Camry; Amount: $5000', 'Damage consistent with reported incident; coverage verified'),
  ('CLM00000001', 'CN00003001', '2025-07-24T05:49:13.959000', 'SIU001', 'SPECIAL_INVESTIGATOR', 'INVESTIGATION_UPDATE', 'Spoke with claimant via phone. They provided additional details about the incident timeline. Witness contact information obtained. Claimant expressed concern about rental car coverage - confirmed policy includes 30 days rental reimbursement up to $50/day. Scheduled vehicle inspection for Thursday at preferred repair facility.', 'Claimant call - provided additional details, inspection scheduled', TRUE, '2026-02-25', 'Claimant Phone: (555) 123-4567; Repair Shop: AutoBody Plus; Rental: Enterprise', 'Claimant cooperative; rental coverage confirmed'),
  ('CLM00000002', 'CN00003002', '2025-07-24T04:09:13.959000', 'SUP002', 'SUPERVISOR', 'DOCUMENT_REVIEW', 'Reviewed submitted documentation including photos of damage, repair estimates from two body shops, and medical records. Photos show impact damage consistent with side collision. Lower estimate selected from certified repair shop. Medical bills total $3502 for ER visit and follow-up. All documentation appears complete.', 'Documentation review complete, all items received', FALSE, NULL, 'Body Shop: Certified Collision; Medical Provider: City Hospital ER', 'All documentation complete and verified'),
  ('CLM00000003', 'CN00003003', '2025-07-24T02:29:13.959000', 'ADJ0003', 'CLAIMS_ADJUSTER', 'PHONE_CALL', 'Investigation update: Conducted recorded statement with insured. Timeline of events verified. No inconsistencies noted. Checked prior claim history - one minor claim 3 years ago, resolved without issue. No red flags identified. Recommend continuing standard claim processing without SIU referral.', 'Investigation update - no red flags, continue processing', FALSE, NULL, 'Prior Claim: CLM-2021-00123; Adjuster: John Smith', 'No fraud indicators; standard processing appropriate'),
  ('CLM00000004', 'CN00003004', '2025-07-24T00:49:13.959000', 'SIU004', 'SPECIAL_INVESTIGATOR', 'SETTLEMENT_NEGOTIATION', 'Settlement offer presented to claimant: $6004 based on repair estimate plus diminished value consideration. Claimant initially requested higher amount citing emotional distress. Explained policy coverage limits and standard calculation methodology. Claimant accepted offer pending receipt of funds within 10 business days.', 'Settlement accepted at $6004', FALSE, NULL, 'Settlement: $6004; Payment Method: Direct Deposit', 'Settlement within guidelines; claimant satisfied'),
  ('CLM00000005', 'CN00003005', '2025-07-23T23:09:13.959000', 'SUP005', 'SUPERVISOR', 'FINAL_REVIEW', 'Property inspection completed by field adjuster. Roof damage assessment: approximately 150 sq ft of shingles damaged by hail. Additional water damage in attic requiring remediation. Total estimate: $11005. Deductible: $1,500. Net payment to insured: $9505. Photos and measurements documented.', 'Property inspection complete, estimate $11005', TRUE, '2026-02-22', 'Property Address: 123 Oak Lane; Contractor: ABC Roofing', 'Enhanced review warranted based on claim characteristics'),
  ('CLM00000006', 'CN00003006', '2025-07-23T21:29:13.959000', 'ADJ0006', 'CLAIMS_ADJUSTER', 'INITIAL_ASSESSMENT', 'SIU referral received for review. Claim exhibits some concerning indicators: policyholder increased coverage 60 days before loss, reported loss occurred with no witnesses, repair estimate seems high for described damage. Recommending enhanced investigation including EUO scheduling and social media review.', 'SIU referral - enhanced investigation recommended', TRUE, '2026-02-23', 'Location: Main St/Oak Ave; Vehicle: 2022 Toyota Camry; Amount: $5006', 'Damage consistent with reported incident; coverage verified'),
  ('CLM00000007', 'CN00003007', '2025-07-23T19:49:13.959000', 'SIU007', 'SPECIAL_INVESTIGATOR', 'INVESTIGATION_UPDATE', 'Medical records review completed. Treatment appears reasonable and necessary for claimed injuries. Primary care physician confirms soft tissue injury consistent with motor vehicle accident. Physical therapy recommended for 6 weeks. No pre-existing conditions affecting claim. Medical reserve set at $5507.', 'Medical records reviewed - treatment reasonable', FALSE, NULL, 'Claimant Phone: (555) 123-4567; Repair Shop: AutoBody Plus; Rental: Enterprise', 'Claimant cooperative; rental coverage confirmed'),
  ('CLM00000008', 'CN00003008', '2025-07-23T18:09:13.959000', 'SUP008', 'SUPERVISOR', 'DOCUMENT_REVIEW', 'Subrogation potential identified. Third party carrier (Nationwide) has accepted liability. Demand letter sent for $8008 representing our total payout plus loss adjustment expenses. Follow-up scheduled for 30 days. Recovery probability estimated at 85%.', 'Subrogation demand sent to third party carrier', FALSE, NULL, 'Body Shop: Certified Collision; Medical Provider: City Hospital ER', 'All documentation complete and verified'),
  ('CLM00000009', 'CN00003009', '2025-07-23T16:29:13.959000', 'ADJ0009', 'CLAIMS_ADJUSTER', 'PHONE_CALL', 'Supervisor review completed. Claim handling meets all guidelines. Payment properly authorized and processed. File documentation complete and organized. No corrective actions needed. Claim ready for closure. Final payment: $7009. Total claim duration: 23 days.', 'Supervisor review passed - ready for closure', FALSE, NULL, 'Prior Claim: CLM-2021-00123; Adjuster: John Smith', 'No fraud indicators; standard processing appropriate'),
  ('CLM00000010', 'CN00003010', '2025-07-23T14:49:13.959000', 'SIU010', 'SPECIAL_INVESTIGATOR', 'SETTLEMENT_NEGOTIATION', 'Fraud indicators detected during routine review. Claimant provided inconsistent statements regarding vehicle location at time of theft. GPS records from connected car service show vehicle was at different location than reported. Referring to SIU for full investigation. Claim payment suspended pending outcome.', 'Fraud indicators detected - SIU referral', TRUE, '2026-02-20', 'Settlement: $6010; Payment Method: Direct Deposit', 'Settlement within guidelines; claimant satisfied'),
  ('CLM00000011', 'CN00003011', '2025-07-23T13:09:13.959000', 'SUP011', 'SUPERVISOR', 'FINAL_REVIEW', 'Follow-up call with repair facility. Parts on backorder - ETA 2 weeks. Rental extension authorized for insured. Updated claimant on timeline. They expressed frustration with delay but understood circumstances. Documented goodwill gesture of waiving $100 deductible based on inconvenience and policyholder tenure of 8 years.', 'Parts delay - rental extended, updated claimant', TRUE, '2026-02-21', 'Property Address: 123 Oak Lane; Contractor: ABC Roofing', 'Enhanced review warranted based on claim characteristics'),
  ('CLM00000012', 'CN00003012', '2025-07-23T11:29:13.959000', 'ADJ0012', 'CLAIMS_ADJUSTER', 'INITIAL_ASSESSMENT', 'Initial claim assessment completed. Policyholder reported collision at Main St and Oak Ave intersection. Police report obtained confirms other party at fault. Vehicle damage appears consistent with reported incident. Recommend proceeding with standard processing. Estimated repair cost: $5012. Coverage verified - comprehensive and collision in force.', 'Initial assessment complete; recommend standard processing', FALSE, NULL, 'Location: Main St/Oak Ave; Vehicle: 2022 Toyota Camry; Amount: $5012', 'Damage consistent with reported incident; coverage verified'),
  ('CLM00000013', 'CN00003013', '2025-07-23T09:49:13.959000', 'SIU013', 'SPECIAL_INVESTIGATOR', 'INVESTIGATION_UPDATE', 'Spoke with claimant via phone. They provided additional details about the incident timeline. Witness contact information obtained. Claimant expressed concern about rental car coverage - confirmed policy includes 30 days rental reimbursement up to $50/day. Scheduled vehicle inspection for Thursday at preferred repair facility.', 'Claimant call - provided additional details, inspection scheduled', FALSE, NULL, 'Claimant Phone: (555) 123-4567; Repair Shop: AutoBody Plus; Rental: Enterprise', 'Claimant cooperative; rental coverage confirmed'),
  ('CLM00000014', 'CN00003014', '2025-07-23T08:09:13.959000', 'SUP014', 'SUPERVISOR', 'DOCUMENT_REVIEW', 'Reviewed submitted documentation including photos of damage, repair estimates from two body shops, and medical records. Photos show impact damage consistent with side collision. Lower estimate selected from certified repair shop. Medical bills total $3514 for ER visit and follow-up. All documentation appears complete.', 'Documentation review complete, all items received', FALSE, NULL, 'Body Shop: Certified Collision; Medical Provider: City Hospital ER', 'All documentation complete and verified'),
  ('CLM00000015', 'CN00003015', '2025-07-23T06:29:13.959000', 'ADJ0015', 'CLAIMS_ADJUSTER', 'PHONE_CALL', 'Investigation update: Conducted recorded statement with insured. Timeline of events verified. No inconsistencies noted. Checked prior claim history - one minor claim 3 years ago, resolved without issue. No red flags identified. Recommend continuing standard claim processing without SIU referral.', 'Investigation update - no red flags, continue processing', TRUE, '2026-02-25', 'Prior Claim: CLM-2021-00123; Adjuster: John Smith', 'No fraud indicators; standard processing appropriate'),
  ('CLM00000016', 'CN00003016', '2025-07-23T04:49:13.959000', 'SIU016', 'SPECIAL_INVESTIGATOR', 'SETTLEMENT_NEGOTIATION', 'Settlement offer presented to claimant: $6016 based on repair estimate plus diminished value consideration. Claimant initially requested higher amount citing emotional distress. Explained policy coverage limits and standard calculation methodology. Claimant accepted offer pending receipt of funds within 10 business days.', 'Settlement accepted at $6016', TRUE, '2026-02-26', 'Settlement: $6016; Payment Method: Direct Deposit', 'Settlement within guidelines; claimant satisfied'),
  ('CLM00000017', 'CN00003017', '2025-07-23T03:09:13.959000', 'SUP017', 'SUPERVISOR', 'FINAL_REVIEW', 'Property inspection completed by field adjuster. Roof damage assessment: approximately 150 sq ft of shingles damaged by hail. Additional water damage in attic requiring remediation. Total estimate: $11017. Deductible: $1,500. Net payment to insured: $9517. Photos and measurements documented.', 'Property inspection complete, estimate $11017', FALSE, NULL, 'Property Address: 123 Oak Lane; Contractor: ABC Roofing', 'Enhanced review warranted based on claim characteristics'),
  ('CLM00000018', 'CN00003018', '2025-07-23T01:29:13.959000', 'ADJ0018', 'CLAIMS_ADJUSTER', 'INITIAL_ASSESSMENT', 'SIU referral received for review. Claim exhibits some concerning indicators: policyholder increased coverage 60 days before loss, reported loss occurred with no witnesses, repair estimate seems high for described damage. Recommending enhanced investigation including EUO scheduling and social media review.', 'SIU referral - enhanced investigation recommended', FALSE, NULL, 'Location: Main St/Oak Ave; Vehicle: 2022 Toyota Camry; Amount: $5018', 'Damage consistent with reported incident; coverage verified'),
  ('CLM00000019', 'CN00003019', '2025-07-22T23:49:13.959000', 'SIU019', 'SPECIAL_INVESTIGATOR', 'INVESTIGATION_UPDATE', 'Medical records review completed. Treatment appears reasonable and necessary for claimed injuries. Primary care physician confirms soft tissue injury consistent with motor vehicle accident. Physical therapy recommended for 6 weeks. No pre-existing conditions affecting claim. Medical reserve set at $5519.', 'Medical records reviewed - treatment reasonable', FALSE, NULL, 'Claimant Phone: (555) 123-4567; Repair Shop: AutoBody Plus; Rental: Enterprise', 'Claimant cooperative; rental coverage confirmed'),
  ('CLM00000020', 'CN00003020', '2025-07-22T22:09:13.959000', 'SUP020', 'SUPERVISOR', 'DOCUMENT_REVIEW', 'Subrogation potential identified. Third party carrier (Nationwide) has accepted liability. Demand letter sent for $8020 representing our total payout plus loss adjustment expenses. Follow-up scheduled for 30 days. Recovery probability estimated at 85%.', 'Subrogation demand sent to third party carrier', TRUE, '2026-02-23', 'Body Shop: Certified Collision; Medical Provider: City Hospital ER', 'All documentation complete and verified'),
