  ('PH00000026', 'EM00000026', 'POL00000026', '2026-02-16T16:49:50.074000', 'OUTBOUND', 'claims@insurance.com', 'customer26@email.com', 'Adding new vehicle to policy', 'Hi, I just purchased a new vehicle and need to add it to my policy. Details: 2024 Honda Accord EX, VIN: 1HGCV1F3XPA123456. Please provide a quote for adding this vehicle and let me know what documents you need. I would like coverage to start immediately.', 'COVERAGE_INQUIRY', 'COVERAGE_QUESTION', '0.3600', 'NEUTRAL', 'LOW', FALSE, NULL),
  ('PH00000028', 'EM00000028', 'POL00000028', '2026-02-16T15:09:50.074000', 'INBOUND', 'customer28@email.com', 'support@insurance.com', 'RE: Follow-up on your inquiry', 'Thank you for your response. Ive reviewed the information you provided and have one follow-up question: Can I make a partial payment this month and pay the remainder next month without penalty? My financial situation is temporarily tight but will improve soon.', 'CLAIMS', 'NOTIFICATION', '0.3800', 'NEUTRAL', 'LOW', TRUE, '16.50'),
  ('PH00000030', 'EM00000030', 'POL00000030', '2026-02-16T13:29:50.074000', 'INBOUND', 'customer30@email.com', 'claims@insurance.com', 'Question about my claim status', 'Hello, I filed a claim last week (claim number CLM-00000030) and havent heard anything since. Can you please provide an update on the status? Im concerned about the timeline as I need to get my car repaired soon. Thank you for your help.', 'CLAIMS', 'STATUS_INQUIRY', '0.4000', 'NEUTRAL', 'LOW', TRUE, '17.50'),
  ('PH00000032', 'EM00000032', 'POL00000032', '2026-02-16T11:49:50.074000', 'OUTBOUND', 'claims@insurance.com', 'customer32@email.com', 'Billing inquiry - payment not reflected', 'I made my premium payment of $132 on the 15th but its still showing as unpaid on my account. I have the bank confirmation showing the payment was processed. Can you please look into this? I dont want my policy to lapse due to your error.', 'BILLING', 'PAYMENT_ISSUE', '0.4200', 'NEUTRAL', 'LOW', FALSE, NULL),
  ('PH00000034', 'EM00000034', 'POL00000034', '2026-02-16T10:09:50.074000', 'INBOUND', 'customer34@email.com', 'support@insurance.com', 'Extremely disappointed with service', 'I am EXTREMELY disappointed with how my claim has been handled. It has been over a month and I still dont have resolution. Every time I call I get transferred to different people and no one can help me. This is unacceptable customer service. I am considering switching to another insurance company. Someone needs to call me TODAY to resolve this.', 'COMPLAINT', 'ESCALATION', '-0.7600', 'NEGATIVE', 'HIGH', TRUE, '19.50'),
  ('PH00000036', 'EM00000036', 'POL00000036', '2026-02-16T08:29:50.074000', 'INBOUND', 'customer36@email.com', 'claims@insurance.com', 'Coverage question for upcoming trip', 'Hi, Im planning a trip to Europe next month and wanted to confirm what coverage I have while traveling abroad. Specifically, does my auto policy cover rental cars in foreign countries? If not, what additional coverage would you recommend? Thanks!', 'COVERAGE_INQUIRY', 'COVERAGE_QUESTION', '0.4600', 'NEUTRAL', 'LOW', TRUE, '20.50'),
  ('PH00000038', 'EM00000038', 'POL00000038', '2026-02-16T06:49:50.074000', 'OUTBOUND', 'claims@insurance.com', 'customer38@email.com', 'RE: Your claim has been approved', 'Dear Valued Customer, We are pleased to inform you that your claim CLM-00000038 has been approved. The settlement amount of $2038 will be deposited to your account within 5-7 business days. Thank you for your patience throughout this process. Please dont hesitate to contact us if you have any questions.', 'CLAIMS', 'NOTIFICATION', '0.6800', 'POSITIVE', 'LOW', FALSE, NULL),
  ('PH00000040', 'EM00000040', 'POL00000040', '2026-02-16T05:09:50.074000', 'INBOUND', 'customer40@email.com', 'support@insurance.com', 'Appeal of claim denial', 'I am writing to formally appeal the denial of my claim CLM-00000040. I believe this decision was made in error. The damage occurred through no fault of my own and is clearly covered under my policy terms. I have attached additional documentation supporting my case. Please review and reconsider this decision.', 'CLAIMS', 'STATUS_INQUIRY', '-0.5000', 'NEGATIVE', 'MEDIUM', TRUE, '22.50'),
  ('PH00000042', 'EM00000042', 'POL00000042', '2026-02-16T03:29:50.074000', 'INBOUND', 'customer42@email.com', 'claims@insurance.com', 'Question about deductible', 'Quick question - if I increase my deductible from $500 to $1000, how much would my premium decrease? Im trying to lower my monthly payments and want to understand my options. Thanks!', 'BILLING', 'PAYMENT_ISSUE', '0.1200', 'NEUTRAL', 'LOW', TRUE, '23.50'),
  ('PH00000044', 'EM00000044', 'POL00000044', '2026-02-16T01:49:50.074000', 'OUTBOUND', 'claims@insurance.com', 'customer44@email.com', 'General policy question', 'Hello, I have a general question about my policy. What exactly is covered under the comprehensive portion? I want to make sure I understand my coverage before I need to use it. Thanks for your help.', 'COMPLAINT', 'ESCALATION', '0.1400', 'NEUTRAL', 'LOW', FALSE, NULL),
  ('PH00000046', 'EM00000046', 'POL00000046', '2026-02-16T00:09:50.074000', 'INBOUND', 'customer46@email.com', 'support@insurance.com', 'URGENT: Need to file a claim', 'I need to file a claim IMMEDIATELY. My car was hit while parked overnight. There is significant damage to the drivers side door and fender. Please call me as soon as possible at (555) 123-4567. This is urgent as I need the vehicle for work. Policy number: POL-00000092', 'COVERAGE_INQUIRY', 'COVERAGE_QUESTION', '0.1600', 'NEUTRAL', 'HIGH', TRUE, '3.00'),
  ('PH00000048', 'EM00000048', 'POL00000048', '2026-02-15T22:29:50.074000', 'INBOUND', 'customer48@email.com', 'claims@insurance.com', 'Request to update policy information', 'Hi, I recently moved to a new address and need to update my policy. My new address is 456 Oak Street, Apt 7B, New York, NY 10001. Also, my phone number has changed to (555) 987-6543. Please update your records and send me a confirmation.', 'CLAIMS', 'NOTIFICATION', '0.1800', 'NEUTRAL', 'LOW', TRUE, '4.00'),
  ('PH00000050', 'EM00000050', 'POL00000050', '2026-02-15T20:49:50.074000', 'OUTBOUND', 'claims@insurance.com', 'customer50@email.com', 'Thank you for the quick resolution', 'I just wanted to send a quick note to thank your team for the excellent service on my recent claim. Sarah from the claims department was incredibly helpful and professional. The entire process was smooth and the check arrived faster than expected. Its nice to know my insurance company is there when I need them!', 'CLAIMS', 'STATUS_INQUIRY', '0.9000', 'POSITIVE', 'LOW', FALSE, NULL),
  ('PH00000052', 'EM00000052', 'POL00000052', '2026-02-15T19:09:50.074000', 'INBOUND', 'customer52@email.com', 'support@insurance.com', 'Cancellation request', 'Please cancel my policy effective at the end of this month. I have found coverage elsewhere at a better rate. Please confirm the cancellation and any refund I may be entitled to for the unused premium portion. My policy number is POL-00000104', 'BILLING', 'PAYMENT_ISSUE', '-0.2800', 'NEUTRAL', 'LOW', TRUE, '6.00'),
  ('PH00000054', 'EM00000054', 'POL00000054', '2026-02-15T17:29:50.074000', 'INBOUND', 'customer54@email.com', 'claims@insurance.com', 'Documents attached as requested', 'As requested, please find attached the following documents: 1) Police report 2) Photos of damage 3) Repair estimate from ABC Auto Body. Let me know if you need anything else to process my claim. Looking forward to hearing from you soon.', 'COMPLAINT', 'ESCALATION', '0.2400', 'NEUTRAL', 'LOW', TRUE, '7.00'),
