/*=============================================================================
  Insurance HOL (Semantic View -> Cortex Agent with CoCo in Snowsight)
  ADMIN SETUP - run once, as a user who can use ACCOUNTADMIN, SECURITYADMIN and SYSADMIN.
  How to run: Snowsight > Projects > Workspaces > + Add new > SQL file > paste > Run All.
  Runtime: about 1 minute.

  BEFORE RUNNING - edit two things:
    (a) Section 1: cross-region inference, if your account has it DISABLED
    (b) Section 4: the list of attendee user names

  Creates
    HOL_ATTENDEE_ROLE      role for every attendee (CoCo, Cortex Analyst/Agents/Search,
                           read on sample data, create objects in the LAB schema)
    HOL_WH                 XSMALL warehouse, auto-suspend 60 s
    HOL_INSURANCE_DB.DATA  6 synthetic insurance tables, 36-45 rows each, READ-ONLY
    HOL_INSURANCE_DB.LAB   shared working schema; attendees create their semantic view and
                           agent here, suffixed with their user name (e.g. *_JSMITH)
  and sets each attendee's DEFAULT_ROLE / DEFAULT_WAREHOUSE to HOL_ATTENDEE_ROLE / HOL_WH
  (required: CoCo in Snowsight and Cortex Agents always run as the user's default role).
  Teardown: admin_teardown.sql
=============================================================================*/

-- 1. Account prerequisites (ACCOUNTADMIN) -------------------------------------------------
USE ROLE ACCOUNTADMIN;
SHOW PARAMETERS LIKE 'CORTEX_ENABLED_CROSS_REGION' IN ACCOUNT;
-- CoCo in Snowsight and the lab's agent (orchestration model: auto) need cross-region inference.
-- If the value above is DISABLED, uncomment and choose a scope your data-residency policy allows
-- (e.g. 'AWS_US', 'AWS_EU', 'ANY_REGION'):
-- ALTER ACCOUNT SET CORTEX_ENABLED_CROSS_REGION = 'ANY_REGION';
SHOW PARAMETERS LIKE 'CORTEX_CODE_SNOWSIGHT_DAILY_EST_CREDIT_LIMIT_PER_USER' IN ACCOUNT;
-- 0 means CoCo in Snowsight is switched off for everyone; raise it for the lab if so.
SHOW PARAMETERS LIKE 'CORTEX_MODELS_ALLOWLIST' IN ACCOUNT;
-- Account-wide ceiling for every role. ALL (the default) lets the grant in section 2 expose every
-- model. If it is NONE or a list, models outside it stay blocked; to open all models:
-- ALTER ACCOUNT SET CORTEX_MODELS_ALLOWLIST = 'ALL';

-- 2. Attendee role + AI access ------------------------------------------------------------
USE ROLE SECURITYADMIN;
CREATE ROLE IF NOT EXISTS HOL_ATTENDEE_ROLE COMMENT = 'Insurance HOL attendees';
GRANT ROLE HOL_ATTENDEE_ROLE TO ROLE SYSADMIN;                -- standard role hierarchy

USE ROLE ACCOUNTADMIN;
GRANT DATABASE ROLE SNOWFLAKE.COPILOT_USER      TO ROLE HOL_ATTENDEE_ROLE;   -- CoCo in Snowsight
GRANT DATABASE ROLE SNOWFLAKE.CORTEX_USER       TO ROLE HOL_ATTENDEE_ROLE;   -- Cortex Analyst / Search / AI functions
GRANT DATABASE ROLE SNOWFLAKE.CORTEX_AGENT_USER TO ROLE HOL_ATTENDEE_ROLE;   -- Cortex Agents
GRANT USE AI FUNCTIONS ON ACCOUNT               TO ROLE HOL_ATTENDEE_ROLE;   -- in case it was revoked from PUBLIC
-- Model access: ALL models available in the account, current and future (matters when the account
-- restricts Cortex models with RBAC). Covers whatever model the agent's auto orchestration picks and every model
-- in CoCo's picker.
CALL SNOWFLAKE.MODELS.CORTEX_BASE_MODELS_REFRESH();
GRANT APPLICATION ROLE SNOWFLAKE."CORTEX-MODEL-ROLE-ALL" TO ROLE HOL_ATTENDEE_ROLE;

-- 3. Warehouse, database, sample data, lab schema (SYSADMIN) ------------------------------
USE ROLE SYSADMIN;
CREATE WAREHOUSE IF NOT EXISTS HOL_WH
  WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE
  COMMENT = 'Insurance HOL warehouse';
GRANT USAGE, OPERATE ON WAREHOUSE HOL_WH TO ROLE HOL_ATTENDEE_ROLE;
GRANT USAGE ON WAREHOUSE HOL_WH TO ROLE SECURITYADMIN;   -- section 4 and the teardown script run as SECURITYADMIN
USE WAREHOUSE HOL_WH;

CREATE DATABASE IF NOT EXISTS HOL_INSURANCE_DB COMMENT = 'Insurance HOL';
CREATE SCHEMA IF NOT EXISTS HOL_INSURANCE_DB.DATA COMMENT = 'Insurance HOL sample data (read-only for attendees)';
CREATE SCHEMA IF NOT EXISTS HOL_INSURANCE_DB.LAB  COMMENT = 'Insurance HOL shared working schema; objects are suffixed _<USERNAME>';
USE SCHEMA HOL_INSURANCE_DB.DATA;

-- 3a. Sample data: subset of github.com/sfc-gh-csharkey/Sample_Data_Financial_Services/Insurance
-- POLICYHOLDERS (45 rows)
CREATE OR REPLACE TABLE POLICYHOLDERS (
	POLICYHOLDER_ID VARCHAR(20) NOT NULL,
	FIRST_NAME VARCHAR(50),
	LAST_NAME VARCHAR(50),
	EMAIL VARCHAR(100),
	PHONE VARCHAR(20),
	DATE_OF_BIRTH DATE,
	GENDER VARCHAR(10),
	ADDRESS_LINE1 VARCHAR(200),
	CITY VARCHAR(100),
	STATE VARCHAR(2),
	ZIP_CODE VARCHAR(10),
	COUNTRY VARCHAR(50) DEFAULT 'USA',
	OCCUPATION VARCHAR(100),
	ANNUAL_INCOME NUMBER(15,2),
	CREDIT_SCORE NUMBER(3,0),
	CUSTOMER_SINCE DATE,
	RISK_TIER VARCHAR(20),
	LIFETIME_VALUE NUMBER(15,2),
	CHURN_RISK_SCORE NUMBER(5,4),
	CREATED_AT TIMESTAMP_NTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	primary key (POLICYHOLDER_ID)
);

-- POLICIES (45 rows)
CREATE OR REPLACE TABLE POLICIES (
	POLICY_ID VARCHAR(20) NOT NULL,
	POLICYHOLDER_ID VARCHAR(20),
	POLICY_TYPE VARCHAR(50),
	PRODUCT_NAME VARCHAR(100),
	EFFECTIVE_DATE DATE,
	EXPIRATION_DATE DATE,
	STATUS VARCHAR(20),
	PREMIUM_AMOUNT NUMBER(12,2),
	PREMIUM_FREQUENCY VARCHAR(20),
	COVERAGE_AMOUNT NUMBER(15,2),
	DEDUCTIBLE NUMBER(10,2),
	UNDERWRITING_CLASS VARCHAR(30),
	RISK_SCORE NUMBER(5,4),
	AGENTS_ID VARCHAR(20),
	CHANNEL VARCHAR(30),
	RENEWAL_COUNT NUMBER(3,0),
	CREATED_AT TIMESTAMP_NTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	primary key (POLICY_ID)
);

-- CLAIMS (36 rows)
CREATE OR REPLACE TABLE CLAIMS (
	CLAIM_ID VARCHAR(20) NOT NULL,
	POLICY_ID VARCHAR(20),
	POLICYHOLDER_ID VARCHAR(20),
	CLAIM_DATE DATE,
	INCIDENT_DATE DATE,
	REPORT_DATE DATE,
	CLAIM_TYPE VARCHAR(50),
	DESCRIPTION VARCHAR(16777216),
	LOCATION_CITY VARCHAR(100),
	LOCATION_STATE VARCHAR(2),
	CLAIMED_AMOUNT NUMBER(15,2),
	APPROVED_AMOUNT NUMBER(15,2),
	PAID_AMOUNT NUMBER(15,2),
	STATUS VARCHAR(30),
	ADJUSTER_ID VARCHAR(20),
	RESOLUTION_DATE DATE,
	FRAUD_FLAG BOOLEAN DEFAULT FALSE,
	FRAUD_SCORE NUMBER(5,4),
	SUBROGATION_FLAG BOOLEAN DEFAULT FALSE,
	LITIGATION_FLAG BOOLEAN DEFAULT FALSE,
	CREATED_AT TIMESTAMP_NTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	primary key (CLAIM_ID)
);

-- CLAIM_NOTES (42 rows)
CREATE OR REPLACE TABLE CLAIM_NOTES (
	NOTE_ID VARCHAR(20) NOT NULL,
	CLAIM_ID VARCHAR(20),
	NOTE_DATE TIMESTAMP_NTZ(9),
	AUTHOR_ID VARCHAR(20),
	AUTHOR_ROLE VARCHAR(50),
	NOTE_TYPE VARCHAR(50),
	CONTENT VARCHAR(16777216),
	SUMMARY VARCHAR(500),
	ACTION_REQUIRED BOOLEAN DEFAULT FALSE,
	ACTION_DUE_DATE DATE,
	EXTRACTED_ENTITIES VARCHAR(16777216),
	KEY_FINDINGS VARCHAR(16777216),
	CREATED_AT TIMESTAMP_NTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	primary key (NOTE_ID)
);

-- CUSTOMER_EMAILS (45 rows)
CREATE OR REPLACE TABLE CUSTOMER_EMAILS (
	EMAIL_ID VARCHAR(20) NOT NULL,
	POLICYHOLDER_ID VARCHAR(20),
	POLICY_ID VARCHAR(20),
	EMAIL_DATE TIMESTAMP_NTZ(9),
	DIRECTION VARCHAR(10),
	FROM_ADDRESS VARCHAR(200),
	TO_ADDRESS VARCHAR(200),
	SUBJECT VARCHAR(300),
	BODY VARCHAR(16777216),
	CATEGORY VARCHAR(50),
	INTENT VARCHAR(50),
	SENTIMENT_SCORE NUMBER(5,4),
	SENTIMENT_LABEL VARCHAR(20),
	URGENCY VARCHAR(20),
	REQUIRES_RESPONSE BOOLEAN,
	RESPONSE_TIME_HOURS NUMBER(6,2),
	CREATED_AT TIMESTAMP_NTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	primary key (EMAIL_ID)
);

-- RISK_ASSESSMENTS (45 rows)
CREATE OR REPLACE TABLE RISK_ASSESSMENTS (
	ASSESSMENT_ID VARCHAR(20) NOT NULL,
	POLICYHOLDER_ID VARCHAR(20),
	ASSESSMENT_DATE DATE,
	ASSESSMENT_TYPE VARCHAR(50),
	UNDERWRITER_ID VARCHAR(20),
	HEALTH_SCORE NUMBER(3,0),
	LIFESTYLE_RISK VARCHAR(30),
	OCCUPATION_RISK VARCHAR(30),
	LOCATION_RISK VARCHAR(30),
	PRIOR_CLAIMS_COUNT NUMBER(5,0),
	PRIOR_CLAIMS_AMOUNT NUMBER(15,2),
	CREDIT_BASED_SCORE NUMBER(3,0),
	OVERALL_RISK_GRADE VARCHAR(5),
	RECOMMENDATION VARCHAR(500),
	NOTES VARCHAR(16777216),
	CREATED_AT TIMESTAMP_NTZ(9) DEFAULT CURRENT_TIMESTAMP(),
	primary key (ASSESSMENT_ID)
);

-- 3b. Grants: read-only on DATA, create-only on LAB ------------------------------------------
GRANT USAGE  ON DATABASE HOL_INSURANCE_DB                     TO ROLE HOL_ATTENDEE_ROLE;
GRANT USAGE  ON SCHEMA   HOL_INSURANCE_DB.DATA                TO ROLE HOL_ATTENDEE_ROLE;
GRANT SELECT ON ALL TABLES IN SCHEMA HOL_INSURANCE_DB.DATA    TO ROLE HOL_ATTENDEE_ROLE;
GRANT USAGE  ON SCHEMA   HOL_INSURANCE_DB.LAB                 TO ROLE HOL_ATTENDEE_ROLE;
GRANT CREATE SEMANTIC VIEW, CREATE AGENT, CREATE CORTEX SEARCH SERVICE, CREATE TABLE, CREATE VIEW
  ON SCHEMA HOL_INSURANCE_DB.LAB TO ROLE HOL_ATTENDEE_ROLE;

-- 4. Attendees: grant role + set defaults (SECURITYADMIN) -----------------------------------
--    <== EDIT the list. Use the "name" column of SHOW USERS exactly (case matters for names
--        such as e-mails). Re-run just this block to add late joiners.
--    SCIM note: if users are provisioned by Okta / Entra ID, the IdP may overwrite defaults on
--    its next sync; set defaultRole / defaultWarehouse in the IdP instead.
USE ROLE SECURITYADMIN;
USE WAREHOUSE HOL_WH;
EXECUTE IMMEDIATE $$
DECLARE
  attendees ARRAY DEFAULT ARRAY_CONSTRUCT(
    'JSMITH',
    'AKUMAR',
    'jane.doe@corp.com'
  );
  usr VARCHAR;
  report VARCHAR DEFAULT '';
BEGIN
  FOR i IN 0 TO ARRAY_SIZE(attendees) - 1 DO
    usr := '"' || attendees[i]::VARCHAR || '"';
    GRANT ROLE HOL_ATTENDEE_ROLE TO USER IDENTIFIER(:usr);
    ALTER USER IDENTIFIER(:usr) SET DEFAULT_ROLE = HOL_ATTENDEE_ROLE DEFAULT_WAREHOUSE = HOL_WH;
    report := report || usr || CHR(10);
  END FOR;
  RETURN 'Configured:' || CHR(10) || report;
END;
$$;

-- 5. Verify ------------------------------------------------------------------------------------
USE ROLE SYSADMIN;
USE WAREHOUSE HOL_WH;
SELECT 'POLICYHOLDERS' AS table_name, COUNT(*) AS row_count FROM HOL_INSURANCE_DB.DATA.POLICYHOLDERS UNION ALL
SELECT 'POLICIES',         COUNT(*) FROM HOL_INSURANCE_DB.DATA.POLICIES         UNION ALL
SELECT 'CLAIMS',           COUNT(*) FROM HOL_INSURANCE_DB.DATA.CLAIMS           UNION ALL
SELECT 'CLAIM_NOTES',      COUNT(*) FROM HOL_INSURANCE_DB.DATA.CLAIM_NOTES      UNION ALL
SELECT 'CUSTOMER_EMAILS',  COUNT(*) FROM HOL_INSURANCE_DB.DATA.CUSTOMER_EMAILS  UNION ALL
SELECT 'RISK_ASSESSMENTS', COUNT(*) FROM HOL_INSURANCE_DB.DATA.RISK_ASSESSMENTS
ORDER BY table_name;
-- Expected: CLAIM_NOTES 42, CLAIMS 36, CUSTOMER_EMAILS 45, POLICIES 45, POLICYHOLDERS 45, RISK_ASSESSMENTS 45
SHOW GRANTS TO ROLE HOL_ATTENDEE_ROLE;
SHOW GRANTS OF ROLE HOL_ATTENDEE_ROLE;   -- the attendees
